    this.geometry=new T.BufferGeometry();this.geometry.setAttribute('position',new T.BufferAttribute(this.position,3).setUsage(T.DynamicDrawUsage));this.geometry.setAttribute('size',new T.BufferAttribute(this.sizes,1).setUsage(T.DynamicDrawUsage));this.geometry.setAttribute('opacity',new T.BufferAttribute(this.alpha,1).setUsage(T.DynamicDrawUsage));
    this.geometry.setAttribute('rotationAttribute',new T.BufferAttribute(this.rotations,1));this.geometry.setAttribute('tintAttribute',new T.BufferAttribute(this.tints,3));this.geometry.setAttribute('shapeAttribute',new T.BufferAttribute(this.shapes,1));this.geometry.setAttribute('glowAttribute',new T.BufferAttribute(this.glows,1));
