    this.material=new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,uniforms:{tint:{value:new T.Color()},scale:{value:1},glow:{value:1},smoke:{value:0}},vertexShader:`attribute float rotationAttribute;varying float vRotation;attribute float size; attribute float opacity;attribute vec3 tintAttribute;attribute float shapeAttribute;attribute float glowAttribute;attribute float smokeAttribute;varying float vSmoke;varying vec3 vTint;varying float vShape;varying float vGlow; uniform float scale; varying float vOpacity; void main(){vRotation=rotationAttribute;vSmoke=smokeAttribute;vTint=tintAttribute;vShape=shapeAttribute;vGlow=glowAttribute;vOpacity=opacity;vec4 mv=modelViewMatrix*vec4(position,1.0);gl_Position=projectionMatrix*mv;gl_PointSize=clamp(size*scale/max(1.0,-mv.z),1.0,180.0);}`,fragmentShader:`varying float vRotation;varying float vSmoke;varying vec3 vTint;varying float vShape;varying float vGlow;uniform vec3 tint;uniform float glow;uniform float smoke;varying float vOpacity;void main(){vec2 uv=(gl_PointCoord-vec2(0.5))*2.0;uv=mat2(cos(vRotation),-sin(vRotation),sin(vRotation),cos(vRotation))*uv;if(vShape>1.5&&vShape<2.5&&abs(vRotation)>0.0001)uv*=1.41421356;float r=length(uv);if(vShape>0.5&&vShape<1.5)r*=1.0+0.35*cos(atan(uv.y,uv.x)*5.0);if(vShape>1.5&&vShape<2.5)r=max(abs(uv.x),abs(uv.y));if(vShape>2.5&&vShape<3.5)r=abs(uv.x)+abs(uv.y);if(r>1.0)discard;float core=1.0-smoothstep(0.05,0.4,r);float halo=exp(-r*r*5.0)*(1.0-r);float falloff=mix(core,core+halo*0.7,vGlow);falloff=mix(falloff,exp(-r*r*3.5)*(1.0-r),vSmoke);if(vShape>3.5)falloff=smoothstep(0.55,0.7,r)*(1.0-smoothstep(0.8,1.0,r));if(vShape>1.5&&vShape<3.5)falloff=1.0-smoothstep(0.8,1.0,r);gl_FragColor=vec4(vTint*(1.0+core*vGlow),falloff*vOpacity);#include <tonemapping_fragment>\n#include <colorspace_fragment>}`.replace(';#include',';\n#include')});
